package main

import "fmt"

func main() {
	var n int
	fmt.Scan(&n)
	prices := make([]int, n)
	for i := range prices {
		fmt.Scan(&prices[i])
	}
	var q int
	fmt.Scan(&q)
	for ; q > 0; q-- {
		var budget int
		fmt.Scan(&budget)
		best := -1
		i, j := 0, n-1
		for i < j {
			sum := prices[i] + prices[j]
			if sum <= budget {
				if sum > best {
					best = sum
				}
				i++
			} else {
				j--
			}
		}
		if best == -1 {
			fmt.Printf("budget %d: none\n", budget)
		} else {
			fmt.Printf("budget %d: %d\n", budget, best)
		}
	}
}

steps.body:
A **window** is a run of neighbors, such as 3 days in a row. Adding up every window from scratch costs k steps per window. Sliding it costs two: when the window moves right by one, one value enters and one leaves.

```go harness
package main

import "fmt"

func main() {
	nums := []int{2, 1, 5, 1, 3, 2}
	k := 3
	{{code}}
	fmt.Println(best, bestStart)
}
```

```go
sum := 0
for i := 0; i < k; i++ {
	sum += nums[i] // the first window
}
best, bestStart := sum, 0
for i := k; i < len(nums); i++ {
	sum += nums[i] - nums[i-k] // nums[i] enters, nums[i-k] leaves
	if sum > best {
		best, bestStart = sum, i-k+1
	}
}
```

After the move, the window is `nums[i-k+1]` through `nums[i]`, so it starts at `i-k+1`. Using `>` and not `>=` keeps the first window on a tie. The whole scan is O(n) no matter how big k is.

Watch the edges: the first loop needs at least k values, and when k equals the length there is only one window.

example.code:
package main

import "fmt"

func main() {
	var n, k int
	fmt.Scan(&n, &k)
	sales := make([]int, n)
	for i := range sales {
		fmt.Scan(&sales[i])
	}

	sum := 0
	for i := 0; i < k; i++ {
		sum += sales[i]
	}
	best, bestStart := sum, 0
	for i := k; i < n; i++ {
		sum += sales[i] - sales[i-k]
		if sum > best {
			best, bestStart = sum, i-k+1
		}
	}
	fmt.Printf("best %d days: %d (days %d to %d)\n", k, best, bestStart+1, bestStart+k)
}

